INSERT INTO master.sources (id, source_name, source_type, publisher, source_url, publication_date, retrieved_at, source_year, license, description, notes, data_status) VALUES ('SRC-GOI-CENSUS-2011', 'Census of India 2011 - Primary Census Abstract Punjab', 'census', 'Office of the Registrar General & Census Commissioner, India', 'https://censusindia.gov.in/census.website/data/census-tables', '2013-04-30', '2026-03-01T10:00:00Z', 2011, 'Government Open Data License - India (GODL)', 'Primary demographic, worker classification, and literacy data for Punjab villages and towns. Explicitly labeled 2011.', 'Historical benchmark. Never label as current population.', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.sources (id, source_name, source_type, publisher, source_url, publication_date, retrieved_at, source_year, license, description, notes, data_status) VALUES ('SRC-GOI-MSME-PMEGP', 'Prime Minister''s Employment Generation Programme (PMEGP) Operational Guidelines', 'official_government', 'Ministry of Micro, Small & Medium Enterprises / KVIC', 'https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp', '2022-05-13', '2026-03-01T10:00:00Z', 2022, 'Public Domain / Official Government Policy', 'Credit-linked subsidy scheme offering 15-35% subsidy for micro enterprises with capex up to Rs 50 Lakhs (mfg) / Rs 20 Lakhs (services).', 'Version 2.0 updated in May 2022 enhancing project cost limits.', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.sources (id, source_name, source_type, publisher, source_url, publication_date, retrieved_at, source_year, license, description, notes, data_status) VALUES ('SRC-GOI-MOFPI-PMFME', 'PM Formalisation of Micro food processing Enterprises (PMFME) Scheme Guidelines', 'official_government', 'Ministry of Food Processing Industries, Government of India', 'https://pmfme.mofpi.gov.in/', '2021-01-15', '2026-03-01T10:00:00Z', 2021, 'Public Domain / Official Government Policy', 'Centrally sponsored scheme providing 35% credit-linked capital subsidy up to Rs 10 Lakhs for micro food processing enterprises.', 'Active under Atmanirbhar Bharat Abhiyan.', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.sources (id, source_name, source_type, publisher, source_url, publication_date, retrieved_at, source_year, license, description, notes, data_status) VALUES ('SRC-GOI-DAHD-AHIDF', 'Animal Husbandry Infrastructure Development Fund (AHIDF) Guidelines', 'official_government', 'Department of Animal Husbandry and Dairying, Ministry of FAHD, GoI', 'https://ahidf.udyamimitra.in/', '2020-07-20', '2026-03-01T10:00:00Z', 2020, 'Public Domain / Official Government Policy', 'Financial support for dairy processing, value addition infrastructure and animal feed plants. 3% interest subvention, up to 90% loan.', 'Credit guarantee up to 25% under CGFTAH managed by NABSanrakshan.', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.sources (id, source_name, source_type, publisher, source_url, publication_date, retrieved_at, source_year, license, description, notes, data_status) VALUES ('SRC-GOI-PMMY-MUDRA', 'Pradhan Mantri MUDRA Yojana (PMMY) Policy Framework', 'official_government', 'MUDRA Ltd. / Department of Financial Services, Ministry of Finance', 'https://www.mudra.org.in/', '2024-07-23', '2026-03-01T10:00:00Z', 2024, 'Public Domain / Official Government Policy', 'Non-corporate, non-farm small/micro enterprises loans: Shishu (up to 50k), Kishore (50k-5L), Tarun (5L-10L), and Tarun Plus (10L-20L under Union Budget 2024).', 'Collateral-free micro finance facility.', 'official') ON CONFLICT (id) DO NOTHING;
