INSERT INTO master.schemes (id, name, provider, scheme_type, description, official_url, active, data_status) VALUES ('SCH-PMEGP', 'Prime Minister''s Employment Generation Programme', 'Ministry of Micro, Small and Medium Enterprises (MoMSME) / KVIC', 'credit_linked_subsidy', 'Credit-linked subsidy program aimed at generating self-employment micro-enterprises in non-farm sector.', 'https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp', TRUE, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.schemes (id, name, provider, scheme_type, description, official_url, active, data_status) VALUES ('SCH-PMFME', 'PM Formalisation of Micro food processing Enterprises Scheme', 'Ministry of Food Processing Industries (MoFPI)', 'credit_linked_grant', 'Centrally sponsored scheme providing 35% capital subsidy for upgrading and formalizing micro food processing units.', 'https://pmfme.mofpi.gov.in/', TRUE, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.schemes (id, name, provider, scheme_type, description, official_url, active, data_status) VALUES ('SCH-AHIDF', 'Animal Husbandry Infrastructure Development Fund', 'Department of Animal Husbandry and Dairying (DAHD), MoFAHD', 'interest_subvention', 'Incentivizes investments in dairy processing, value-addition infrastructure, meat processing and animal feed plants.', 'https://ahidf.udyamimitra.in/', TRUE, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.schemes (id, name, provider, scheme_type, description, official_url, active, data_status) VALUES ('SCH-MUDRA', 'Pradhan Mantri MUDRA Yojana', 'MUDRA Ltd. / Department of Financial Services', 'refinance_collateral_free', 'Provides formal collateral-free loans up to Rs 20 Lakhs across Shishu, Kishore, Tarun, and Tarun Plus categories.', 'https://www.mudra.org.in/', TRUE, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.scheme_versions (id, scheme_id, version, effective_from, effective_to, project_cost_min, project_cost_max, funding_percent, funding_max, interest_rate, tenure_months, moratorium_months, subsidy_information, collateral_information, margin_requirements, source_id, source_document_id, eligibility_summary, confidence, data_status) VALUES ('SCHVER-PMEGP-V2', 'SCH-PMEGP', 2.0, '2022-05-13', '2027-03-31', 100000.0, 5000000.0, 90.0, 4500000.0, 9.5, 84, 6, 'Rural General: 25% margin money subsidy. Rural Special Category (Women/SC/ST/OBC/Ex-Servicemen): 35% margin money subsidy.', 'CGTMSE coverage without third party guarantee for loans up to Rs 2 Crore.', 'General: 10% own contribution. Special: 5% own contribution.', 'SRC-GOI-MSME-PMEGP', 'DOC-PMEGP-GUIDELINES-2022', 'Individual above 18 years; at least VIII pass for projects > Rs 10L in manufacturing. Greenfield projects only.', 0.98, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.scheme_versions (id, scheme_id, version, effective_from, effective_to, project_cost_min, project_cost_max, funding_percent, funding_max, interest_rate, tenure_months, moratorium_months, subsidy_information, collateral_information, margin_requirements, source_id, source_document_id, eligibility_summary, confidence, data_status) VALUES ('SCHVER-PMFME-V1', 'SCH-PMFME', 1.0, '2020-06-29', '2026-03-31', 200000.0, 4000000.0, 90.0, 3600000.0, 9.25, 72, 6, 'Credit-linked capital subsidy at 35% of eligible project cost with a maximum ceiling of Rs 10 Lakh per enterprise.', 'CGTMSE coverage eligible through participating commercial banks.', 'Minimum 10% own contribution from the beneficiary enterprise.', 'SRC-GOI-MOFPI-PMFME', 'DOC-PMFME-GUIDELINES-2021', 'Existing micro food enterprises or new individual/SHG food enterprises in ODOP or approved food processing categories.', 0.98, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.scheme_versions (id, scheme_id, version, effective_from, effective_to, project_cost_min, project_cost_max, funding_percent, funding_max, interest_rate, tenure_months, moratorium_months, subsidy_information, collateral_information, margin_requirements, source_id, source_document_id, eligibility_summary, confidence, data_status) VALUES ('SCHVER-AHIDF-V1', 'SCH-AHIDF', 1.0, '2020-07-20', '2027-03-31', 1000000.0, 100000000.0, 90.0, 90000000.0, 7.0, 96, 24, '3% interest subvention for 8 years; credit guarantee up to 25% under CGFTAH.', 'Covered under Credit Guarantee Scheme for Animal Husbandry up to 25% of loan sanction.', 'Micro/Small units: minimum 10% own equity contribution.', 'SRC-GOI-DAHD-AHIDF', 'DOC-AHIDF-GUIDELINES-2020', 'Farmer Producer Organizations (FPOs), MSMEs, Section 8 companies, private entrepreneurs setting up dairy/feed units.', 0.97, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.scheme_versions (id, scheme_id, version, effective_from, effective_to, project_cost_min, project_cost_max, funding_percent, funding_max, interest_rate, tenure_months, moratorium_months, subsidy_information, collateral_information, margin_requirements, source_id, source_document_id, eligibility_summary, confidence, data_status) VALUES ('SCHVER-MUDRA-TARUN', 'SCH-MUDRA', '2024-Update', '2024-07-23', '2027-03-31', 500000.0, 2000000.0, 85.0, 1700000.0, 10.25, 60, 3, 'No direct upfront capital subsidy; subsidizes access to credit through refinance and CGFMU guarantee.', 'Zero collateral requirement. Covered under Credit Guarantee Fund for Micro Units (CGFMU).', '15% own contribution for Tarun loans.', 'SRC-GOI-PMMY-MUDRA', 'DOC-MUDRA-CIRCULAR-2024', 'Non-corporate, non-farm micro enterprises requiring working capital or capex up to Rs 20 Lakhs.', 0.98, 'official') ON CONFLICT (id) DO NOTHING;
